  args: {
    size: 40
  },
  render: () => <Box sx={{
    p: 4
  }}>
      <Stack spacing={4}>
        <Box>
          <MuiTypography variant="h6" sx={{
          mb: 2
        }}>
            User List
          </MuiTypography>
          <Stack spacing={2}>
            {[{
            name: 'Martin Gómez',
            initials: 'MG',
            img: 'https://i.pravatar.cc/150?img=10'
          }, {
            name: 'Camila Muñoz',
            initials: 'CM',
            img: 'https://i.pravatar.cc/150?img=11'
          }, {
            name: 'Felipe Taborda',
            initials: 'FP',
            img: 'https://i.pravatar.cc/150?img=12'
          }].map((user, index) => <Box key={index} sx={{
            display: 'flex',
            alignItems: 'center',
            gap: 2
          }}>
                <Avatar src={user.img} alt={user.name}>
                  {user.initials}
                </Avatar>
                <MuiTypography>{user.name}</MuiTypography>
              </Box>)}
          </Stack>
        </Box>

        <Box>
          <MuiTypography variant="h6" sx={{
          mb: 2
        }}>
            Comment Thread
          </MuiTypography>
          <Stack spacing={2}>
            {[{
            initials: 'MG',
            comment: 'Gran trabajo!'
          }, {
            initials: 'CM',
            comment: 'Gracias por el feedback!'
          }, {
            initials: 'FP',
            comment: 'Estoy ansioso por la próxima iteración.'
          }].map((item, index) => <Box key={index} sx={{
            display: 'flex',
            gap: 2
          }}>
                <Avatar size={32}>{item.initials}</Avatar>
                <Box sx={{
              flex: 1
            }}>
                  <MuiTypography variant="body2">{item.comment}</MuiTypography>
                </Box>
              </Box>)}
          </Stack>
        </Box>

        <Box>
          <MuiTypography variant="h6" sx={{
          mb: 2
        }}>
            Team Members (Small)
          </MuiTypography>
          <Stack direction="row" spacing={1}>
            {['MG', 'CM', 'FP', 'FT', 'JF'].map((initials, index) => <Avatar key={index} size={24}>
                {initials}
              </Avatar>)}
          </Stack>
        </Box>
      </Stack>
    </Box>,
  parameters: {
    layout: 'fullscreen'
  }
